{
  "title": "真实模型链路验收",
  "summary": "三大陆修士逐道求存，叩探界门隐秘。",
  "unresolvedQuestions": [
    {
      "id": "uq_01",
      "question": "界门背后是否连通域外天魔族群？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "uq_02",
      "question": "寿元燃尽后是否存在真灵转生之法？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_03",
      "question": "三大陆界门开启时是否会触发天地灵气守恒律的反向大吞噬？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_04",
      "question": "大乾天朝皇室命修是否秘密掌握借国运转移燃寿反噬之法？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_05",
      "question": "补天阁阁主本尊是否早已突破破虚境迈入主宰境？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "uq_06",
      "question": "主角以命寿换力突破至归一境时，延寿灵泉能否中和其肉身永久衰老的暗伤？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_07",
      "question": "虚空神晶若被大量采集，是否会导致苍冥大陆虚空裂隙提前扩大并崩塌？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_08",
      "question": "太古界门破虚匙共有几柄，补天阁内部是否封存有另外的钥匙残片？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_09",
      "question": "十年前青玄极天界门的无故灵震是否由主角家族或某位通天境强者的秘密燃寿破门引发？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "uq_10",
      "question": "影杀阁乾都刺杀案幕后真凶是否为大乾内部企图夺嫡并推翻宗门妥协路线的皇子？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "audit-power-opening",
      "question": "第1章淬体境、寿元不足十年燃寿五年，与乾坤逆命真解允许神海境以上、十年至三十年消耗及最低十年寿元矛盾；第24章同日连续燃寿也违反三十日冷却。须确定残篇规则或重修正文，并重新评审。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-resource-definitions",
      "question": "已补充绝命死息 res_15、诸天通宝 res_16 的资源提案并修正势力引用；新增品阶、材质、发行与保存规则尚需对照正文核验，不能视为已确立事实。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-travel-rules",
      "question": "已按正文撤销200／500灵石与代付债务假设，记录三枚中品灵石打点和火晶换舱。火晶数量、资源品阶换算、玄令绝对庇护与政治查验冲突、北境上岸凭证及回师供给仍需核对；第55章信物玉佩已存在，但不能自动推断为官方入境许可。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-tier-exceptions",
      "question": "终局提案改为断供触发tech_17反噬，不再靠破虚直接击败主宰；96–99章取消不足三年强发动tech_10、无门槛驾驭art_13/14和逆死长生。第1–85章的晋阶寿耗、连续燃寿、碎空瞬灭刃三十年成本与钥匙使用仍须逐项返修；所有原成本门槛均保留。",
      "blocking": true,
      "status": "open"
    }
  ]
}

